window.__resumeFile = { name: "Shrida Sali \u2014 Product Designer.pdf", b64: "" };

window.__resumeBlobUrl = function () {
  if (window.__resumeUrl) return window.__resumeUrl;
  var bin = atob(window.__resumeFile.b64), n = bin.length, arr = new Uint8Array(n);
  for (var i = 0; i < n; i++) arr[i] = bin.charCodeAt(i);
  window.__resumeUrl = URL.createObjectURL(new Blob([arr], { type: "application/pdf" }));
  return window.__resumeUrl;
};

window.__downloadResume = function () {
  var a = document.createElement("a");
  a.href = window.__resumeBlobUrl();
  a.download = window.__resumeFile.name;
  document.body.appendChild(a);
  a.click();
  a.remove();
};

window.__openResume = function () {
  var url = window.__resumeBlobUrl();

  // 1. try a real new tab; Chrome blocks blob: navigation from some embedded contexts
  var w = null;
  try { w = window.open(url, "_blank", "noopener"); } catch (e) { w = null; }
  if (w && !w.closed) return;

  // 2. fall back to an in-page viewer with a download escape hatch
  var prev = document.getElementById("__resume-overlay");
  if (prev) prev.remove();

  var ov = document.createElement("div");
  ov.id = "__resume-overlay";
  ov.style.cssText = "position:fixed;inset:0;z-index:9999;display:flex;flex-direction:column;background:rgba(23,21,26,.62);backdrop-filter:blur(6px);opacity:0;transition:opacity .25s ease";

  var barEl = document.createElement("div");
  barEl.style.cssText = "display:flex;align-items:center;justify-content:space-between;gap:20px;padding:18px 22px;color:#fff;font:600 13px/1 'Montserrat',system-ui,sans-serif";
  barEl.innerHTML = '<span style="font:500 11px/1 \'JetBrains Mono\',ui-monospace,monospace;letter-spacing:.16em;opacity:.85">RESUME — SHRIDA SALI</span>';

  var actions = document.createElement("div");
  actions.style.cssText = "display:flex;align-items:center;gap:10px";

  var dl = document.createElement("button");
  dl.textContent = "Download PDF";
  dl.style.cssText = "padding:11px 18px;border-radius:999px;border:0;background:#fff;color:#2E0250;font:600 12px/1 'Montserrat',system-ui,sans-serif;cursor:pointer";
  dl.onclick = window.__downloadResume;

  var close = document.createElement("button");
  close.textContent = "Close";
  close.style.cssText = "padding:11px 18px;border-radius:999px;border:1px solid rgba(255,255,255,.5);background:transparent;color:#fff;font:600 12px/1 'Montserrat',system-ui,sans-serif;cursor:pointer";
  close.onclick = function () { ov.style.opacity = "0"; setTimeout(function () { ov.remove(); }, 250); };

  actions.appendChild(dl);
  actions.appendChild(close);
  barEl.appendChild(actions);

  var stage = document.createElement("div");
  stage.style.cssText = "position:relative;flex:1;margin:0 22px 22px;border-radius:14px;overflow:hidden;background:#faf9fb";
  stage.innerHTML = '<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:34px;text-align:center;font:400 15px/1.6 \'Montserrat\',system-ui,sans-serif;color:rgba(23,21,26,.6)">Your browser blocked the inline preview.<span style="font:500 11px/1 \'JetBrains Mono\',ui-monospace,monospace;letter-spacing:.14em;color:rgba(23,21,26,.45)">USE DOWNLOAD PDF ABOVE</span></div>';

  var frame = document.createElement("iframe");
  frame.src = url;
  frame.style.cssText = "position:absolute;inset:0;width:100%;height:100%;border:0;background:#faf9fb";
  stage.appendChild(frame);

  ov.appendChild(barEl);
  ov.appendChild(stage);
  document.body.appendChild(ov);
  requestAnimationFrame(function () { ov.style.opacity = "1"; });
  setTimeout(function () { ov.style.opacity = "1"; }, 60);

  document.addEventListener("keydown", function esc(e) {
    if (e.key === "Escape") { close.onclick(); document.removeEventListener("keydown", esc); }
  });
};
